// Frozen copies of the place-heading and place-header compositions at 53f9c47, before place-heading became a foundation
// (slice 3, F1.9). The parity test mounts them at their old paths and compares their markup with the foundation.
export const placeHeadingBefore = "<script lang=\"ts\">\n  import { Heading } from '../../index.ts';\n  import type { PlaceIdentity } from '../../../infra/place-identity.ts';\n  import { PhotoCollection } from '../../index.ts';\n  import { catalogPhotos } from '../../../infra/media-source.ts';\n  let { identity, element = $bindable(null) }: { identity: PlaceIdentity; element?: HTMLElement | null } = $props();\n  let failed = $state(false);\n  $effect(() => { identity.media; failed = false; });\n</script>\n\n<!-- The sole semantic page heading stays mounted; chrome mirrors only identity. -->\n<div bind:this={element} class=\"place-heading-content\" data-place-header data-featured-media={identity.media?.kind} data-media-unavailable={failed}>\n  {#if identity.media && !failed}\n    {#if identity.media.kind === 'image' || identity.media.kind === 'gallery'}\n      {@const photos = catalogPhotos(identity.media.kind === 'gallery' ? identity.media.images : [identity.media])}\n      {#key photos.map(photo=>photo.source).join('|')}\n        <PhotoCollection {photos} title={identity.title} header />\n      {/key}\n    {:else}\n      <video data-header-media src={`/media/${encodeURIComponent(identity.media.asset)}`}\n        poster={identity.media.poster ? `/media/${encodeURIComponent(identity.media.poster)}` : undefined}\n        aria-label={identity.media.alt} muted playsinline controls preload=\"metadata\" onerror={() => failed = true}></video>\n    {/if}\n  {/if}\n  <div class=\"place-heading-copy\" data-dock-above>\n    <Heading kind=\"page\" text={identity.title} focusTarget />\n    <p class=\"type-support\" data-place-subtitle>{identity.subtitle}</p>\n  </div>\n</div>\n";
export const placeHeaderBefore = "<script lang=\"ts\">\n  import { Heading } from \"../../index.ts\";\n  import type { CatalogProps } from \"../../types.d.ts\";\n  let { title, subtitle, background }: CatalogProps<\"place-header\"> = $props();\n  let failed = $state(false);\n  $effect(() => { background?.asset; failed = false; });\n</script>\n\n<!-- An embedded heading is content, never a toolbar or scroll owner. -->\n<header class=\"place-heading\" data-embedded-place-heading>\n  <div class=\"flex min-w-0 flex-col gap-1\">\n    {#if background && !failed}<img src={`/media/${encodeURIComponent(background.asset)}`} alt={background.alt} onerror={() => failed = true} />{/if}\n    <Heading kind=\"page\" text={title} />\n    <p class=\"type-support text-muted-foreground\" data-place-subtitle>{subtitle}</p>\n  </div>\n</header>\n";
// The place heading's stylesheet at ff4ad8b, before PlaceHeading mounted Gallery and left the gallery's anatomy to it.
export const placeHeadingCssBefore = "/* One semantic header; its stationary toolbar echo never owns media or actions. */\n.place-heading-content {\n  position:relative; min-width:0; isolation:isolate;\n  padding:calc(var(--catalog-toolbar-inset,12px) + var(--catalog-toolbar-height,44px) + 24px) var(--place-content-inset,42px) 24px;\n  padding-inline-start:calc(var(--place-leading-inset,0px) + var(--place-content-inset,42px));\n}\n.place-heading-copy { display:flex; flex-direction:column; align-items:flex-start; gap:var(--heading-copy-gap); min-width:0; overflow-wrap:anywhere; }\n.place-heading-copy > * { margin:0; max-width:100%; overflow-wrap:anywhere; }\n.place-heading-copy [data-place-title] { outline:none; }\n.place-heading-copy [data-place-subtitle] { color:var(--muted-foreground); max-width:65ch; }\n.place-heading-content[data-featured-media] { display:flex; align-items:flex-end; min-height:min(65dvh,36rem); padding-bottom:32px; }\n[data-header-media] { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; z-index:-2; }\n.place-heading-content[data-featured-media]:not([data-media-unavailable=\"true\"])::before { content:\"\"; position:absolute; inset:0; z-index:-1; pointer-events:none; background:linear-gradient(transparent 35%,var(--catalog-image-shade)); }\n.place-heading-content[data-featured-media]:not([data-media-unavailable=\"true\"]) .place-heading-copy,\n.place-heading-content[data-featured-media]:not([data-media-unavailable=\"true\"]) [data-place-subtitle] { color:var(--catalog-image-foreground); text-shadow:0 1px 4px var(--catalog-image-shade); }\n.place-heading-content[data-featured-media=\"video\"] { padding-bottom:64px; }\n.place-heading-content > [data-header-collection] { position:absolute; inset:0; z-index:0; }\n.place-heading-content[data-featured-media]:has([data-header-collection])::before { content:none; }\n[data-header-collection]::before { content:\"\"; position:absolute; inset:0; z-index:1; pointer-events:none; background:linear-gradient(transparent 35%,var(--catalog-image-shade)); }\n[data-header-collection] > [data-media-open] { z-index:2; }\n.place-heading-content:has([data-header-collection]) .place-heading-copy { position:relative; z-index:2; pointer-events:none; }\n.place-heading-content:has([data-media-dots]) .place-heading-copy { padding-bottom:32px; }\n[data-header-collection] [data-media-dots] { left:calc(50% + var(--place-leading-inset,0px)/2); }\n.place-heading-content[data-featured-media]:not([data-media-unavailable=\"true\"]) [data-place-subtitle] { color:color-mix(in srgb,var(--catalog-image-foreground) 74%,transparent); }\n@media(prefers-contrast:more) { .place-heading-content[data-featured-media]:not([data-media-unavailable=\"true\"]) [data-place-subtitle] { color:var(--catalog-image-foreground); } }\n/* The embedded heading: content inside a place, never a toolbar or scroll owner. */\n.place-heading { display:flex; flex-direction:column; gap:.5rem; }\n";
